--
-- Name: account_redact(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_redact(p jsonb, p_accounts text[]) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  t text := p::text;
  a text;
begin
  foreach a in array p_accounts loop
    t := replace(t, '"' || a || '"', '"[excluded]"');
  end loop;
  return t::jsonb;
end $$;


