-- Name: FUNCTION account_redact(p jsonb, p_accounts text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.account_redact(p jsonb, p_accounts text[]) IS 'Replaces every JSON string and key equal to one of the account names by "[excluded]".';


