-- Name: array_redact(text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.array_redact(p text[], p_accounts text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  select coalesce(array_agg(case when x = any (p_accounts) then '[excluded]' else x end order by o), '{}')
  from unnest(p) with ordinality as t(x, o);
$$;


--
-- Name: FUNCTION array_redact(p text[], p_accounts text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.array_redact(p text[], p_accounts text[]) IS 'Replaces the given account names in a text array by "[excluded]".';


--
-- Name: evidence_minimise(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evidence_minimise(p jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  select case when p::text like '%"email": %' then
    regexp_replace(
      regexp_replace(p::text, '"email": "(?:[^"\\]|\\.)*?@((?:[^"\\]|\\.)*)"', '"emailDomain": "\1"', 'g'),
      '"email": (?:"(?:[^"\\]|\\.)*"|null)', '"emailDomain": null', 'g')::jsonb
  else p end;
$$;


--
-- Name: FUNCTION evidence_minimise(p jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.evidence_minimise(p jsonb) IS 'Replaces every {"email": address} in a snapshot by {"emailDomain": domain}.';


--
-- Name: exclusion_apply(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.exclusion_apply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_accounts text[] := array[new.account];
  v_token    text := '%"' || new.account || '"%';
begin
  update stage2_result s
     set evidence = account_redact(s.evidence, v_accounts),
         features = account_redact(s.features, v_accounts)
   where (s.evidence::text like v_token or s.features::text like v_token)
     and not exists (select 1 from finding f where f.seq = s.seq and f.verdict = 'confirmed');
  update maintainer_set m
     set maintainers = array_redact(m.maintainers, v_accounts),
         added = array_redact(m.added, v_accounts),
         removed = array_redact(m.removed, v_accounts)
   where (new.account = any (m.maintainers) or new.account = any (m.added) or new.account = any (m.removed))
     and not exists (select 1 from finding f where f.seq = m.seq and f.verdict = 'confirmed');
  return new;
end $$;


--
-- Name: FUNCTION exclusion_apply(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.exclusion_apply() IS 'Trigger: a new exclusion cleans the stored snapshots and maintainer sets, except those of events with the verdict "confirmed".';


--
-- Name: features_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.features_check() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_stage smallint := tg_argv[0]::smallint;
  v_bad   text;
begin
  if tg_op = 'UPDATE' and new.features is not distinct from old.features then
    return new;
  end if;
  select coalesce(e->>'id', '(no id)') into v_bad
  from jsonb_array_elements(new.features) e
  where jsonb_typeof(e) <> 'object'
     or jsonb_typeof(e->'id') is distinct from 'string'
     or jsonb_typeof(e->'weight') is distinct from 'number'
     or not exists (select 1 from feature f where f.id = e->>'id' and f.stage = v_stage)
  limit 1;
  if found then
    raise exception 'feature "%" is not a valid stage-% feature (seq %)', v_bad, v_stage, new.seq
      using errcode = 'check_violation';
  end if;
  return new;
end $$;


--
-- Name: FUNCTION features_check(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.features_check() IS 'Trigger: every element of a feature list is an object with an id and a numeric weight, and the id is a feature of the right stage.';


--
-- Name: feed_event_ensure_partitions(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_event_ensure_partitions(p_now timestamp with time zone DEFAULT now()) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  m       date := date_trunc('month', p_now at time zone 'UTC')::date;
  created text[] := '{}';
  part    text;
begin
  for i in 0..1 loop
    part := 'feed_event_' || to_char(m, 'YYYYMM');
    if to_regclass(part) is null then
      execute format('create table %I partition of feed_event for values from (%L) to (%L)',
                     part, m::timestamptz, (m + interval '1 month')::date::timestamptz);
      created := created || part;
    end if;
    m := (m + interval '1 month')::date;
  end loop;
  return created;
end $$;


--
-- Name: FUNCTION feed_event_ensure_partitions(p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.feed_event_ensure_partitions(p_now timestamp with time zone) IS 'Creates the journal partitions for the month of the argument and the next month; returns the names of the new partitions. Runs with the rights of the owner.';


--
-- Name: finding_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finding_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    insert into finding_history (seq, operation, verdict, note, reference)
    values (old.seq, 'delete', old.verdict, old.note, old.reference);
    return old;
  end if;
  if tg_op = 'UPDATE' and new.verdict = old.verdict
     and new.note is not distinct from old.note and new.reference is not distinct from old.reference then
    return new;
  end if;
  insert into finding_history (seq, operation, verdict, note, reference)
  values (new.seq, lower(tg_op), new.verdict, new.note, new.reference);
  return new;
end $$;


--
-- Name: FUNCTION finding_audit(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finding_audit() IS 'Trigger: copies every change of a verdict to finding_history.';


--
-- Name: grant_app_privileges(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_app_privileges() RETURNS text[]
    LANGUAGE plpgsql
    AS $$
declare
  granted text[] := '{}';
begin
  if exists (select 1 from pg_roles where rolname = 'npm_monitor_write') then
    revoke all on all tables in schema public from npm_monitor_write;
    grant select on all tables in schema public to npm_monitor_write;
    revoke select on finding_history from npm_monitor_write;
    grant insert, update, delete on
      feed_event, collector_state, popular_package, stage_cursor, stage1_result, stage1_hourly,
      stage2_result, source_usage, rdap_cache, maintainer_set, retention_run
      to npm_monitor_write;
    grant execute on function feed_event_ensure_partitions(timestamptz), refresh_daily_stats(),
      apply_retention(integer, timestamptz) to npm_monitor_write;
    granted := granted || 'npm_monitor_write'::text;
  end if;

  if exists (select 1 from pg_roles where rolname = 'npm_monitor_web') then
    revoke all on all tables in schema public from npm_monitor_web;
    grant select on all tables in schema public to npm_monitor_web;
    grant insert, update, delete on finding to npm_monitor_web;
    granted := granted || 'npm_monitor_web'::text;
  end if;

  if exists (select 1 from pg_roles where rolname = 'npm_monitor_read') then
    revoke all on all tables in schema public from npm_monitor_read;
    grant select on
      feed_event, collector_state, stage_cursor, popular_package, source, feature,
      stage1_result, stage1_hourly, source_usage, finding, retention_run,
      feature_hit, alert, stage2_result_masked, maintainer_set_masked, daily_stats, data_quality
      to npm_monitor_read;
    granted := granted || 'npm_monitor_read'::text;
  end if;

  return granted;
end $$;


--
-- Name: FUNCTION grant_app_privileges(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.grant_app_privileges() IS 'Applies the access rights of the three application roles to all current objects; called by the migration service after every run.';


--
-- Name: maintainer_set_privacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.maintainer_set_privacy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_accounts text[];
begin
  select array_agg(account) into v_accounts from exclusion;
  if v_accounts is not null then
    new.maintainers := array_redact(new.maintainers, v_accounts);
    new.added := array_redact(new.added, v_accounts);
    new.removed := array_redact(new.removed, v_accounts);
  end if;
  return new;
end $$;


--
-- Name: FUNCTION maintainer_set_privacy(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.maintainer_set_privacy() IS 'Trigger: applies the exclusion list to every new or changed maintainer-set row.';


--
-- Name: mask_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mask_email(p_email text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  select case when p_email ~ '^[^@]+@[^@]+$'
              then left(p_email, 1) || '***@' || split_part(p_email, '@', 2) end;
$_$;


--
-- Name: FUNCTION mask_email(p_email text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mask_email(p_email text) IS 'Masks an e-mail address: "j***@example.org".';


--
-- Name: pseudonym(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pseudonym(p_account text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  select 'user-' || left(encode(sha256(convert_to(p_account, 'UTF8')), 'hex'), 10);
$$;


--
-- Name: FUNCTION pseudonym(p_account text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pseudonym(p_account text) IS 'Stable pseudonym of an account name: "user-" and ten hex digits of its SHA-256.';


