--
-- Name: stage2_result_privacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stage2_result_privacy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_accounts text[];
begin
  new.evidence := evidence_minimise(new.evidence);
  select array_agg(account) into v_accounts from exclusion;
  if v_accounts is not null then
    new.evidence := account_redact(new.evidence, v_accounts);
    new.features := account_redact(new.features, v_accounts);
  end if;
  return new;
end $$;


--
-- Name: FUNCTION stage2_result_privacy(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.stage2_result_privacy() IS 'Trigger: applies evidence_minimise and the exclusion list to every new or changed snapshot.';


