COMMENT ON COLUMN public.stage2_result.enriched_at IS 'When stage 2 stored the result. The retention period counts from this time.';


--
-- Name: COLUMN stage2_result.kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stage2_result.kind IS 'publish — the event carries new versions; metadata — no new version (tags, maintainers); package_missing — the registry no longer has the package; error — the package document could not be read.';


