-- Name: COLUMN stage2_result.versions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stage2_result.versions IS 'Versions published by the event, in publication order. Empty for the other kinds. Read and written as one value, never joined.';


--
-- Name: COLUMN stage2_result.prescore; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stage2_result.prescore IS 'Stage-1 score at enrichment time. A historical value: stage 1 can be recomputed later with new parameters.';


--
-- Name: COLUMN stage2_result.final_score; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stage2_result.final_score IS 'prescore plus the weights of the stage-2 features. Not negative.';


--
-- Name: COLUMN stage2_result.alert; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stage2_result.alert IS 'True when the event raised an alert for the analyst.';


--
