COMMENT ON COLUMN public.stage2_result.engine IS 'Version of the stage-2 engine: "v<version>:<hash of parameters>".';


--
-- Name: COLUMN stage2_result.evidence_purged_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stage2_result.evidence_purged_at IS 'When the retention job removed the snapshot; null while the snapshot is present.';


--
-- Name: alert; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.alert AS
 SELECT s.seq,
    s.package,
    s.event_time,
    s.enriched_at,
    s.kind,
    s.versions,
    r.prescore AS stage1_score,
    s.final_score,
    s.engine,
    ( SELECT array_agg((e.value ->> 'id'::text) ORDER BY (e.value ->> 'id'::text)) AS array_agg
           FROM jsonb_array_elements(s.features) e(value)) AS stage2_features,
    COALESCE(f.verdict, 'open'::text) AS verdict,
    f.reference,
    f.decided_at
   FROM ((public.stage2_result s
     JOIN public.stage1_result r ON ((r.seq = s.seq)))
     LEFT JOIN public.finding f ON ((f.seq = s.seq)))
  WHERE s.alert;


--
-- Name: VIEW alert; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.alert IS 'Alerts with the stage-1 score, the stage-2 feature ids and the current verdict ("open" when there is none).';


