-- Name: feed_event; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.feed_event (
    seq bigint CONSTRAINT feed_event_seq_not_null1 NOT NULL,
    package text CONSTRAINT feed_event_package_not_null1 NOT NULL,
    rev text CONSTRAINT feed_event_rev_not_null1 NOT NULL,
    deleted boolean DEFAULT false CONSTRAINT feed_event_deleted_not_null1 NOT NULL,
    observed_at timestamp with time zone CONSTRAINT feed_event_observed_at_not_null1 NOT NULL,
    observed_after timestamp with time zone,
    CONSTRAINT feed_event_interval_check CHECK (((observed_after IS NULL) OR (observed_after <= observed_at))),
    CONSTRAINT feed_event_package_check CHECK ((package <> ''::text)),
    CONSTRAINT feed_event_precision_check CHECK ((observed_at = date_trunc('milliseconds'::text, observed_at))),
    CONSTRAINT feed_event_rev_check CHECK ((rev ~ '^[0-9]+-'::text)),
    CONSTRAINT feed_event_seq_check CHECK ((seq > 0))
)
PARTITION BY RANGE (observed_at);


