--
-- Name: daily_stats; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.daily_stats AS
 WITH days AS (
         SELECT (generate_series(( SELECT date_trunc('day'::text, (min(feed_event.observed_at) AT TIME ZONE 'UTC'::text)) AS date_trunc
                   FROM public.feed_event), date_trunc('day'::text, (now() AT TIME ZONE 'UTC'::text)), '1 day'::interval))::date AS day
        ), ev AS (
         SELECT ((feed_event.observed_at AT TIME ZONE 'UTC'::text))::date AS day,
            count(*) AS events,
            count(DISTINCT feed_event.package) AS packages
           FROM public.feed_event
          GROUP BY (((feed_event.observed_at AT TIME ZONE 'UTC'::text))::date)
        ), s1 AS (
         SELECT ((stage1_result.event_time AT TIME ZONE 'UTC'::text))::date AS day,
            count(*) AS flagged,
            count(*) FILTER (WHERE stage1_result.candidate) AS candidates
           FROM public.stage1_result
          GROUP BY (((stage1_result.event_time AT TIME ZONE 'UTC'::text))::date)
        ), s2 AS (
         SELECT ((s.event_time AT TIME ZONE 'UTC'::text))::date AS day,
            count(*) AS enriched,
            count(*) FILTER (WHERE s.alert) AS alerts,
            count(*) FILTER (WHERE (s.alert AND (EXISTS ( SELECT 1
                   FROM public.popular_package p
                  WHERE (p.name = s.package))))) AS alerts_popular,
            count(*) FILTER (WHERE (f.verdict = 'confirmed'::text)) AS confirmed,
            count(*) FILTER (WHERE (f.verdict = 'false_positive'::text)) AS false_positive
           FROM (public.stage2_result s
             LEFT JOIN public.finding f ON ((f.seq = s.seq)))
          GROUP BY (((s.event_time AT TIME ZONE 'UTC'::text))::date)
        )
 SELECT d.day,
    (COALESCE(ev.events, (0)::bigint))::integer AS events,
    (COALESCE(ev.packages, (0)::bigint))::integer AS packages,
    (COALESCE(s1.flagged, (0)::bigint))::integer AS flagged,
    (COALESCE(s1.candidates, (0)::bigint))::integer AS candidates,
    (COALESCE(s2.enriched, (0)::bigint))::integer AS enriched,
    (COALESCE(s2.alerts, (0)::bigint))::integer AS alerts,
    (COALESCE(s2.alerts_popular, (0)::bigint))::integer AS alerts_popular,
    (COALESCE(s2.confirmed, (0)::bigint))::integer AS confirmed,
    (COALESCE(s2.false_positive, (0)::bigint))::integer AS false_positive
   FROM (((days d
     LEFT JOIN ev ON ((ev.day = d.day)))
     LEFT JOIN s1 ON ((s1.day = d.day)))
     LEFT JOIN s2 ON ((s2.day = d.day)))
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW daily_stats; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON MATERIALIZED VIEW public.daily_stats IS 'Mart layer. Totals per day (UTC): events, packages, flagged, candidates, enriched, alerts, alerts on popular packages, verdicts. Source of KPI-5. Refreshed daily by refresh_daily_stats().';


