--
-- Name: data_quality; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.data_quality AS
 SELECT 'stage1_result.package equals the journal value'::text AS expectation,
    ( SELECT count(*) AS count
           FROM (public.stage1_result r
             JOIN public.feed_event e ON (((e.seq = r.seq) AND (e.observed_at = r.event_time))))
          WHERE (r.package <> e.package)) AS violations
UNION ALL
 SELECT 'stage2_result.package equals the journal value'::text AS expectation,
    ( SELECT count(*) AS count
           FROM (public.stage2_result s
             JOIN public.feed_event e ON (((e.seq = s.seq) AND (e.observed_at = s.event_time))))
          WHERE (s.package <> e.package)) AS violations
UNION ALL
 SELECT 'maintainer_set.package equals the stage-2 value'::text AS expectation,
    ( SELECT count(*) AS count
           FROM (public.maintainer_set m
             JOIN public.stage2_result s ON ((s.seq = m.seq)))
          WHERE (m.package <> s.package)) AS violations
UNION ALL
 SELECT 'every candidate older than one day has a stage-2 result'::text AS expectation,
    ( SELECT count(*) AS count
           FROM public.stage1_result r
          WHERE (r.candidate AND (r.event_time < (now() - '1 day'::interval)) AND (NOT (EXISTS ( SELECT 1
                   FROM public.stage2_result s
                  WHERE (s.seq = r.seq)))))) AS violations
UNION ALL
 SELECT 'no e-mail address in a stored snapshot'::text AS expectation,
    ( SELECT count(*) AS count
           FROM public.stage2_result
          WHERE ((stage2_result.evidence)::text ~~ '%"email": "%'::text)) AS violations
UNION ALL
 SELECT 'no snapshot without an alert is older than the retention period plus one day'::text AS expectation,
    ( SELECT count(*) AS count
           FROM public.stage2_result s
          WHERE ((NOT s.alert) AND (NOT (s.sources ? 'repeat_of'::text)) AND (s.evidence_purged_at IS NULL) AND (s.evidence <> '{}'::jsonb) AND (s.enriched_at < (now() - '31 days'::interval)))) AS violations
UNION ALL
 SELECT 'no journal row in the default partition'::text AS expectation,
    ( SELECT count(*) AS count
           FROM public.feed_event_default) AS violations;


--
-- Name: VIEW data_quality; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.data_quality IS 'Data-quality report: one row per expectation with the number of rows that break it. All zero on a healthy database.';


