--
-- Name: feature_hit; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.feature_hit AS
 SELECT r.seq,
    (1)::smallint AS stage,
    (e.value ->> 'id'::text) AS feature_id,
    ((e.value ->> 'weight'::text))::real AS weight,
    r.event_time
   FROM public.stage1_result r,
    LATERAL jsonb_array_elements(r.features) e(value)
UNION ALL
 SELECT s.seq,
    (2)::smallint AS stage,
    (e.value ->> 'id'::text) AS feature_id,
    ((e.value ->> 'weight'::text))::real AS weight,
    s.event_time
   FROM public.stage2_result s,
    LATERAL jsonb_array_elements(s.features) e(value);


