--
-- Name: TABLE finding_history; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.finding_history IS 'Audit trail of finding: one row per insert, change or deletion, written by trigger finding_audit. Nobody but the trigger can write here.';


--
-- Name: COLUMN finding_history.id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finding_history.id IS 'Surrogate key in order of the changes.';


--
-- Name: COLUMN finding_history.seq; Type: COMMENT; Schema: public; Owner: -
