--
-- Name: maintainer_change; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.maintainer_change AS
 SELECT m.package,
    m.seq,
    m.observed_at,
    a.account,
    'added'::text AS change
   FROM public.maintainer_set m,
    LATERAL unnest(m.added) a(account)
UNION ALL
 SELECT m.package,
    m.seq,
    m.observed_at,
    a.account,
    'removed'::text AS change
   FROM public.maintainer_set m,
    LATERAL unnest(m.removed) a(account);


--
-- Name: VIEW maintainer_change; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.maintainer_change IS 'One row per account added to or removed from a maintainer set: the relational form of the array columns.';


--
-- Name: maintainer_set_masked; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.maintainer_set_masked AS
 SELECT package,
    seq,
    observed_at,
    ( SELECT COALESCE(array_agg(public.pseudonym(t.x) ORDER BY t.o), '{}'::text[]) AS "coalesce"
           FROM unnest(m.maintainers) WITH ORDINALITY t(x, o)) AS maintainers,
    ( SELECT COALESCE(array_agg(public.pseudonym(t.x) ORDER BY t.o), '{}'::text[]) AS "coalesce"
           FROM unnest(m.added) WITH ORDINALITY t(x, o)) AS added,
    ( SELECT COALESCE(array_agg(public.pseudonym(t.x) ORDER BY t.o), '{}'::text[]) AS "coalesce"
           FROM unnest(m.removed) WITH ORDINALITY t(x, o)) AS removed
   FROM public.maintainer_set m;


--
-- Name: VIEW maintainer_set_masked; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.maintainer_set_masked IS 'maintainer_set with account names replaced by stable pseudonyms; for the read role and for demonstrations.';


