--
-- Name: stage1_hourly; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stage1_hourly (
    hour timestamp with time zone NOT NULL,
    processed integer NOT NULL,
    flagged integer NOT NULL,
    candidates integer NOT NULL,
    CONSTRAINT stage1_hourly_check CHECK (((processed >= 0) AND (flagged >= 0) AND (candidates >= 0) AND (flagged <= processed) AND (candidates <= flagged))),
    CONSTRAINT stage1_hourly_hour_check CHECK ((hour = (date_trunc('hour'::text, (hour AT TIME ZONE 'UTC'::text)) AT TIME ZONE 'UTC'::text)))
);


