--
-- Name: stage2_result_masked; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.stage2_result_masked AS
 SELECT seq,
    package,
    event_time,
    enriched_at,
    kind,
    versions,
    prescore,
    final_score,
    alert,
    ( SELECT COALESCE(jsonb_agg(jsonb_build_object('id', (t.e -> 'id'::text), 'lane', (t.e -> 'lane'::text), 'weight', (t.e -> 'weight'::text)) ORDER BY t.o), '[]'::jsonb) AS "coalesce"
           FROM jsonb_array_elements(s.features) WITH ORDINALITY t(e, o)) AS features,
    sources,
    engine,
    evidence_purged_at
   FROM public.stage2_result s;


